[
    SRSReportParameterAttribute(classstr(METContinuingPermissionNoticeContract))
]
class METContinuingPermissionNoticeDP extends SrsReportDataProviderBase
{
    METContinuingPermissionNoticeHeaderTmp  header;
    METContinuingPermissionNoticeLineTmp    line;

}

Method.Source:
    public void processReport()
    {
        CustTable c;
        select firstonly c;

        Image img = new Image();
        img.setData(CompanyImage::findByRecord(CompanyInfo::find()).Image);        
        header.CompanyLogo = img.getData();
    
        header.ContinuingPermissionNoticeNumber = 'CPN001';
        header.SalesId                          = 'SO090909';
        header.NoticeDate                       = today();
        header.NoticeTimeString                 = time2str(timeNow(), TimeSeparator::Colon, TimeSeparator::Colon);
        // header noticeTime

        header.SendingBranchName                = '[Sending branch]';
        header.SendingBranchAddress             = '1 Road street\nCanberra';
        header.SendingBranchABN                 = '[SB ABN]';
        header.SendingBranchExciseNumber        = '[SB excise]';

        header.ReceivingBranchName              = '[Receiving branch]';
        header.ReceivingBranchAddress           = '1 Street Road\nCanberra';
        header.ReceivingBranchABN               = '[RB ABN]';
        header.ReceivingBranchExciseNumber      = '[RB excise]';

        header.insert();

        int n;
        for(n = 1; n <= 10; n++)
        {
            line.clear();
            line.BondMark                   = strFmt('BondMark%1', n);
            line.ItemName                   = strFmt('Item name %1', n);
            line.BottlesSupplied            = 15;
            line.BottleSize                 = 55;   // string?
            line.PackQty                    = 24;
            line.Strength                   = 4.2;
            line.LtrsAlc                    = 0.33;
            line.ValueTIU                   = 0.9;
            line.TarifItem                  = '2198298212';
            line.Country                    = 'FGMY';
            line.StateCode                  = '21'; // Rename to 'StatCode'
            line.DutyAmount                 = 7.72;
            line.insert();
        }

    }

[SRSReportDataSet(tableStr(METContinuingPermissionNoticeHeaderTmp))]
public METContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;
    return header;
}

[SRSReportDataSet(tableStr(METContinuingPermissionNoticeLineTmp))]
public METContinuingPermissionNoticeLineTmp dsLines()
{
    select line;
    return line;
}
